// Draws the extension icons. Committed PNGs are opaque, so this keeps them
// reproducible: run `node scripts/build-icons.mjs` and the three files are
// regenerated byte for byte.
//
// The mark is the badge itself -- a white question mark on the accent red, in a
// heavy black frame. No image library: a PNG is a few chunks and a deflate
// stream, so it is written here directly.

import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const ACCENT = [0xff, 0x2d, 0x2d];
const BLACK = [0x00, 0x00, 0x00];
const WHITE = [0xff, 0xff, 0xff];

// A 7 x 10 question mark, scaled up by whole pixels so the edges stay hard.
const GLYPH = [
  '.#####.',
  '##...##',
  '##...##',
  '.....##',
  '....##.',
  '...##..',
  '...##..',
  '.......',
  '...##..',
  '...##..',
];

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    table[n] = c;
  }
  return table;
})();

function crc32(buffer) {
  let crc = -1;
  for (let i = 0; i < buffer.length; i += 1) {
    crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ buffer[i]) & 0xff];
  }
  return (crc ^ -1) >>> 0;
}

function chunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([length, body, crc]);
}

/** An 8-bit truecolour PNG from a width*height*3 pixel buffer. */
function encodePng(width, height, pixels) {
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width, 0);
  header.writeUInt32BE(height, 4);
  header[8] = 8; // bit depth
  header[9] = 2; // colour type: truecolour
  header[10] = 0; // deflate
  header[11] = 0; // adaptive filtering
  header[12] = 0; // no interlace

  const stride = width * 3;
  const raw = Buffer.alloc((stride + 1) * height);
  for (let y = 0; y < height; y += 1) {
    raw[y * (stride + 1)] = 0; // filter: none
    pixels.copy(raw, y * (stride + 1) + 1, y * stride, (y + 1) * stride);
  }

  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', header),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

function drawIcon(size) {
  const pixels = Buffer.alloc(size * size * 3);
  const put = (x, y, colour) => {
    if (x < 0 || y < 0 || x >= size || y >= size) return;
    const at = (y * size + x) * 3;
    pixels[at] = colour[0];
    pixels[at + 1] = colour[1];
    pixels[at + 2] = colour[2];
  };

  const frame = Math.max(2, Math.round(size / 16));
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const onFrame = x < frame || y < frame || x >= size - frame || y >= size - frame;
      put(x, y, onFrame ? BLACK : ACCENT);
    }
  }

  const glyphHeight = GLYPH.length;
  const glyphWidth = GLYPH[0].length;
  const scale = Math.max(1, Math.floor((size * 0.7) / glyphHeight));
  const offsetX = Math.round((size - glyphWidth * scale) / 2);
  const offsetY = Math.round((size - glyphHeight * scale) / 2);

  for (let row = 0; row < glyphHeight; row += 1) {
    for (let column = 0; column < glyphWidth; column += 1) {
      if (GLYPH[row][column] !== '#') continue;
      for (let dy = 0; dy < scale; dy += 1) {
        for (let dx = 0; dx < scale; dx += 1) {
          put(offsetX + column * scale + dx, offsetY + row * scale + dy, WHITE);
        }
      }
    }
  }

  return encodePng(size, size, pixels);
}

const root = path.join(import.meta.dirname, '..');
// 48 and 96 ship in the extension; 128 is for the AMO listing page.
[48, 96, 128].forEach((size) => {
  const target = path.join(root, 'icons', `icon-${size}.png`);
  fs.writeFileSync(target, drawIcon(size));
  console.error(`build-icons: wrote icons/icon-${size}.png`);
});
